import { readFileSync, statSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import { SOUND_LIBRARY, isSoundId, soundFor, soundMediaId, soundUrl, type LibrarySound } from './library';

/**
 * The sound library (D-156): what + Sound offers, and the files behind it.
 *
 * The files are generated by `npm run sounds` and committed, so these read
 * them as the browser will — the WAV header and the samples — and hold them to
 * what the catalogue promises: the right length, loop points on whole samples
 * with an exact copy of the loop's ends either side, and no clipping.
 */

/** Every id ever shipped. Projects store them: never rename or remove one. */
const SHIPPED_IDS = [
  'upbeat-pulse', 'lofi-haze', 'corporate-bright', 'cinematic-dawn',
  'whoosh', 'swoosh', 'pop', 'click', 'riser', 'impact', 'chime', 'applause',
];

/** The shortest clip the timeline allows (MIN_AUDIO_CLIP_MS). */
const MIN_CLIP_MS = 300;

type Wav = { readonly sampleRate: number; readonly channels: number; readonly bits: number; readonly samples: Int16Array; readonly bytes: number };

function readWav(sound: LibrarySound): Wav {
  const file = readFileSync(resolve(process.cwd(), 'public', soundUrl(sound).slice(1)));
  const view = new DataView(file.buffer, file.byteOffset, file.byteLength);
  const text = (at: number): string => String.fromCharCode(...file.subarray(at, at + 4));
  expect(text(0)).toBe('RIFF');
  expect(text(8)).toBe('WAVE');
  expect(text(36)).toBe('data');
  const length = view.getUint32(40, true);
  const samples = new Int16Array(length / 2);
  for (let i = 0; i < samples.length; i++) samples[i] = view.getInt16(44 + i * 2, true);
  return {
    channels: view.getUint16(22, true),
    sampleRate: view.getUint32(24, true),
    bits: view.getUint16(34, true),
    samples,
    bytes: file.byteLength,
  };
}

describe('the catalogue', () => {
  it('keeps every id it has ever shipped, unique and url-safe', () => {
    const ids = SOUND_LIBRARY.map((sound) => sound.id);
    expect(new Set(ids).size).toBe(ids.length);
    for (const id of SHIPPED_IDS) expect(ids).toContain(id);
    for (const id of ids) expect(id).toMatch(/^[a-z0-9]+(-[a-z0-9]+)*$/);
  });

  it('offers four background loops and eight effects', () => {
    expect(SOUND_LIBRARY.filter((s) => s.kind === 'background')).toHaveLength(4);
    expect(SOUND_LIBRARY.filter((s) => s.kind === 'effect')).toHaveLength(8);
  });

  it('says where every sound came from', () => {
    for (const sound of SOUND_LIBRARY) expect(sound.licence, sound.id).toMatch(/Original/);
  });

  it('loops every background sound over whole bars, on whole samples, with room either side', () => {
    for (const sound of SOUND_LIBRARY.filter((s) => s.kind === 'background')) {
      const { loop, bpm, bars } = sound;
      if (!loop || bpm === undefined || bars === undefined) throw new Error(`${sound.id} needs loop points, a tempo and bars`);
      expect(loop.endMs - loop.startMs, sound.id).toBe((bars * 4 * 60_000) / bpm);
      for (const ms of [loop.startMs, loop.endMs, sound.durationMs]) {
        expect(Number.isInteger((ms * sound.sampleRate) / 1000), `${sound.id} at ${ms}ms`).toBe(true);
      }
      expect(loop.startMs, sound.id).toBeGreaterThanOrEqual(50);
      expect(sound.durationMs - loop.endMs, sound.id).toBeGreaterThanOrEqual(50);
    }
  });

  it('plays effects once, each long enough to be a clip of its own', () => {
    for (const sound of SOUND_LIBRARY.filter((s) => s.kind === 'effect')) {
      expect(sound.loop, sound.id).toBeUndefined();
      expect(sound.durationMs, sound.id).toBeGreaterThanOrEqual(MIN_CLIP_MS);
    }
  });

  it('starts background music quieter than effects, so they read over it', () => {
    for (const music of SOUND_LIBRARY.filter((s) => s.kind === 'background')) {
      for (const effect of SOUND_LIBRARY.filter((s) => s.kind === 'effect')) {
        expect(music.defaultGainDb).toBeLessThan(effect.defaultGainDb);
      }
    }
  });
});

describe('media ids', () => {
  it('round-trips through its own namespace', () => {
    for (const sound of SOUND_LIBRARY) {
      const id = soundMediaId(sound);
      expect(id).toBe(`sound:${sound.id}`);
      expect(isSoundId(id)).toBe(true);
      expect(soundFor(id)).toBe(sound);
    }
  });

  it('does not claim anyone else’s media', () => {
    for (const id of ['upload:abc', 'sample:dune', 'music:placeholder-drift', 'whoosh']) {
      expect(isSoundId(id), id).toBe(false);
      expect(soundFor(id), id).toBeUndefined();
    }
    // Ours by its prefix, but not a sound we have: never a crash, just nothing.
    expect(soundFor('sound:nope')).toBeUndefined();
  });

  it('is fetched from public/sounds', () => {
    const first = SOUND_LIBRARY[0];
    if (!first) throw new Error('expected a sound');
    expect(soundUrl(first)).toBe(`/sounds/${first.id}.wav`);
  });
});

describe('the files', () => {
  it('are mono 16-bit PCM at the stated rate and exactly the stated length', () => {
    for (const sound of SOUND_LIBRARY) {
      const wav = readWav(sound);
      expect(wav.channels, sound.id).toBe(1);
      expect(wav.bits, sound.id).toBe(16);
      expect(wav.sampleRate, sound.id).toBe(sound.sampleRate);
      expect(wav.samples.length, sound.id).toBe((sound.durationMs * sound.sampleRate) / 1000);
    }
  });

  it('never clip: every peak stays under −1dBFS', () => {
    const ceiling = Math.round(32767 * 10 ** (-0.9 / 20));
    for (const sound of SOUND_LIBRARY) {
      let peak = 0;
      for (const v of readWav(sound).samples) peak = Math.max(peak, Math.abs(v));
      expect(peak, sound.id).toBeLessThanOrEqual(ceiling);
      expect(peak, `${sound.id} is silent`).toBeGreaterThan(ceiling / 4);
    }
  });

  it('carry an exact copy of each loop’s end before it and its start after it', () => {
    for (const sound of SOUND_LIBRARY) {
      const { loop } = sound;
      if (!loop) continue;
      const { samples, sampleRate } = readWav(sound);
      const start = (loop.startMs * sampleRate) / 1000;
      const end = (loop.endMs * sampleRate) / 1000;
      for (let k = 0; k < samples.length - end; k++) {
        if (samples[end + k] !== samples[start + k]) throw new Error(`${sound.id}: post-roll differs at ${k}`);
      }
      for (let k = 1; k <= start; k++) {
        if (samples[start - k] !== samples[end - k]) throw new Error(`${sound.id}: pre-roll differs at ${k}`);
      }
    }
  });

  it('end every effect in silence, so nothing is cut off', () => {
    for (const sound of SOUND_LIBRARY.filter((s) => s.kind === 'effect')) {
      const { samples, sampleRate } = readWav(sound);
      const tail = samples.subarray(samples.length - sampleRate / 100);
      for (const v of tail) expect(Math.abs(v), sound.id).toBeLessThan(40);
    }
  });

  it('stay under 4MB together', () => {
    const total = SOUND_LIBRARY.reduce((sum, sound) => sum + statSync(resolve(process.cwd(), 'public', soundUrl(sound).slice(1))).size, 0);
    expect(total).toBeLessThan(4_000_000);
  });
});
